struct Checkout {                                 // Context
    let pricing: (Double) -> Double               // Strategy as a closure
    func total(_ qty: Double) -> Double { pricing(qty) }
}

let retail = Checkout(pricing: { $0 * 9.99 })
let bulk   = Checkout(pricing: { $0 > 100 ? $0 * 7.49 : $0 * 9.99 })
